		if match.Reason != "" {
			reasons = append(reasons, match.Reason)
		}
	}

	logEntry := memoryloop.InjectionLog{
		SessionID:         event.SessionID,
		PromptPreview:     truncatePromptPreview(event.Prompt, 500),
		InjectedMemoryIDs: ids,
		InjectedAt:        now,
		Reason:            strings.Join(reasons, ", "),
